import { z } from 'zod';
import { ContentHash } from './harness.ts';
import { Identifier } from './ids.ts';

export const GENERATED_IMAGE_MAX_BYTES = 32 * 1024 * 1024;
/** Original generated bytes; input-image normalization must never silently resize these. */
export const BinaryArtifact = z.strictObject({
  version: z.literal(1),
  kind: z.literal('image'),
  mime: z.literal('image/png'),
  bytes: z.int().min(1).max(GENERATED_IMAGE_MAX_BYTES),
  width: z.int().min(1).max(8192),
  height: z.int().min(1).max(8192),
  sha256: ContentHash,
  blobRef: Identifier,
});
export type BinaryArtifact = z.infer<typeof BinaryArtifact>;
export const GenerateImageArgs = z.strictObject({
  references: z
    .array(Identifier)
    .min(1)
    .max(3)
    .refine((ids) => new Set(ids).size === ids.length, 'duplicate image references')
    .optional(),
  profileId: Identifier,
  prompt: z.string().min(1).max(32000),
  size: z.enum(['1024x1024', '1536x1024', '1024x1536']).optional(),
  quality: z.enum(['low', 'medium', 'high']).optional(),
});
export type GenerateImageArgs = z.infer<typeof GenerateImageArgs>;
/** Explicit image operation configuration, separate from a text model's inferred capabilities. */
export const ImageGenerationProfile = z.strictObject({
  bindingHash: ContentHash.optional(),
  profileId: Identifier,
  modelProfileId: Identifier,
  modelId: z.string().min(1).max(200),
  api: z.literal('openai-images'),
  timeoutMs: z.int().min(1000).max(600000),
  maxCallsPerRun: z.int().min(1).max(16),
  /** A configured upper price bound; unknown pricing is never treated as zero. */
  maxCostUsdPerCall: z.number().positive().max(100),
});
export type ImageGenerationProfile = z.infer<typeof ImageGenerationProfile>;
export interface ImageGenerationOwner {
  runId: string;
  executionId: string;
  attemptNo: number;
  effectId: string;
  artifactVersionId: string;
}
export interface ImageGenerationResult {
  media: BinaryArtifact;
  usage: { inputTokens: number | null; outputTokens: number | null };
  /** Provider token usage is evidence; it does not prove the final billed price. */
  costUsd: number | null;
}
